// Get all incoming items from the previous n8n node
const items = $input.all();

const students = [];
const seenIds = new Set();

// Process each incoming item
for (const item of items) {
    try {
        // Each item contains a "text" field with JSON string data
        let student = item.json.text;

        // Parse the JSON string into a JavaScript object
        if (typeof student === "string") {
            student = JSON.parse(student);
        }

        // Skip invalid records
        if (!student || typeof student !== "object" || Array.isArray(student)) {
            continue;
        }

        // Clean text fields
        const studentId = String(student.Student_ID ?? "")
            .trim()
            .toUpperCase();

        const name = String(student.Name ?? "")
            .trim()
            .replace(/\s+/g, " ");

        const email = String(student.Email ?? "")
            .trim()
            .toLowerCase();

        const phone = String(student.Phone ?? "")
            .trim()
            .replace(/\D/g, "");

        const course = String(student.Course ?? "")
            .trim()
            .replace(/\s+/g, " ");

        const city = String(student.City ?? "")
            .trim()
            .replace(/\s+/g, " ");

        const enrolledDate = String(student.Enrolled_Date ?? "")
            .trim();

        // Validate email
        const emailValid =
            /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

        // Validate Indian mobile number
        const phoneValid =
            /^[6-9]\d{9}$/.test(phone);

        // Validate date in YYYY-MM-DD format
        let dateValid = false;

        if (/^\d{4}-\d{2}-\d{2}$/.test(enrolledDate)) {
            const date = new Date(enrolledDate + "T00:00:00Z");

            dateValid =
                !isNaN(date.getTime()) &&
                date.toISOString().slice(0, 10) === enrolledDate;
        }

        // Detect duplicate student IDs
        const duplicateId =
            studentId !== "" && seenIds.has(studentId);

        if (studentId !== "") {
            seenIds.add(studentId);
        }

        // Normalize Fee_Paid
        const feeValue = student.Fee_Paid;

        const feePaid =
            feeValue === true ||
            feeValue === 1 ||
            ["true", "1", "yes"].includes(
                String(feeValue ?? "").trim().toLowerCase()
            );

        // Add cleaned student record
        students.push({
            json: {
                Student_ID: studentId,
                Name: name,
                Email: emailValid ? email : null,
                Phone: phoneValid ? phone : null,
                Course: course,
                Fee_Paid: feePaid,
                City: city,
                Enrolled_Date: dateValid ? enrolledDate : null,

                Validation: {
                    Email_Valid: emailValid,
                    Phone_Valid: phoneValid,
                    Date_Valid: dateValid,
                    Duplicate_Student_ID: duplicateId
                }
            }
        });

    } catch (error) {
        // Skip malformed JSON records
        continue;
    }
}

// Return cleaned records to n8n
return students;
